/**
 * UnitSync Shared UI Utilities
 * Replaces browser alerts with custom modals and toasts
 * Follows UI_DESIGN.md section 4 & 5
 */

// Toast notification helper
function showToast(message, type = 'info', duration = 4000) {
    let container = document.querySelector('.toast-container');
    if (!container) {
        container = document.createElement('div');
        container.className = 'toast-container';
        document.body.appendChild(container);
    }

    const toast = document.createElement('div');
    toast.className = `toast toast-${type}`;
    toast.setAttribute('role', 'alert');

    // Choose SVG icon based on type
    let iconSvg = '';
    if (type === 'success') {
        iconSvg = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="var(--success)" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg>';
    } else if (type === 'error') {
        iconSvg = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="var(--error)" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="8" x2="12" y2="12"></line><line x1="12" y1="16" x2="12.01" y2="16"></line></svg>';
    } else if (type === 'warning') {
        iconSvg = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="var(--warning)" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"></path><line x1="12" y1="9" x2="12" y2="13"></line><line x1="12" y1="17" x2="12.01" y2="17"></line></svg>';
    } else {
        iconSvg = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="var(--info)" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="16" x2="12" y2="12"></line><line x1="12" y1="8" x2="12.01" y2="8"></line></svg>';
    }

    toast.innerHTML = `
        <div style="flex-shrink:0;">${iconSvg}</div>
        <div style="flex:1;">${message}</div>
    `;

    container.appendChild(toast);

    // Trigger enter animation
    requestAnimationFrame(() => {
        toast.classList.add('show');
    });

    // Auto dismiss
    setTimeout(() => {
        toast.classList.remove('show');
        toast.addEventListener('transitionend', () => {
            toast.remove();
        });
    }, duration);
}

// Confirmation modal helper (returns a Promise<boolean>)
function showConfirm(options = {}) {
    const title = options.title || 'Confirm Action';
    const message = options.message || 'Are you sure you want to proceed?';
    const confirmText = options.confirmText || 'Confirm';
    const cancelText = options.cancelText || 'Cancel';
    const isDanger = options.isDanger || false;

    return new Promise((resolve) => {
        const overlay = document.createElement('div');
        overlay.className = 'modal-overlay';
        overlay.setAttribute('role', 'dialog');
        overlay.setAttribute('aria-modal', 'true');

        overlay.innerHTML = `
            <div class="modal-card">
                <div class="modal-header">
                    <h3>${title}</h3>
                </div>
                <div class="modal-body">
                    ${message}
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-secondary btn-sm" id="modal-cancel-btn">${cancelText}</button>
                    <button type="button" class="btn ${isDanger ? 'btn-danger' : 'btn-primary'} btn-sm" id="modal-confirm-btn">${confirmText}</button>
                </div>
            </div>
        `;

        document.body.appendChild(overlay);

        // Open modal with transition
        requestAnimationFrame(() => {
            overlay.classList.add('open');
        });

        const cancelBtn = overlay.querySelector('#modal-cancel-btn');
        const confirmBtn = overlay.querySelector('#modal-confirm-btn');

        function cleanup(result) {
            overlay.classList.remove('open');
            document.removeEventListener('keydown', handleKey);
            setTimeout(() => {
                overlay.remove();
                resolve(result);
            }, 200);
        }

        function handleKey(e) {
            if (e.key === 'Escape') {
                cleanup(false);
            }
        }

        cancelBtn.addEventListener('click', () => cleanup(false));
        confirmBtn.addEventListener('click', () => cleanup(true));
        overlay.addEventListener('click', (e) => {
            if (e.target === overlay) cleanup(false);
        });
        document.addEventListener('keydown', handleKey);

        confirmBtn.focus();
    });
}

// Prompt modal with textarea helper (for rejection / deactivation reasons)
function showPromptModal(options = {}) {
    const title = options.title || 'Reason Required';
    const message = options.message || 'Please provide details:';
    const placeholder = options.placeholder || 'Enter reason here...';
    const confirmText = options.confirmText || 'Submit';
    const isDanger = options.isDanger || false;

    return new Promise((resolve) => {
        const overlay = document.createElement('div');
        overlay.className = 'modal-overlay';
        overlay.setAttribute('role', 'dialog');
        overlay.setAttribute('aria-modal', 'true');

        overlay.innerHTML = `
            <div class="modal-card">
                <div class="modal-header">
                    <h3>${title}</h3>
                </div>
                <div class="modal-body">
                    <p style="margin-bottom: 12px;">${message}</p>
                    <textarea id="modal-prompt-input" class="form-control" rows="3" placeholder="${placeholder}" required autofocus></textarea>
                    <span id="modal-prompt-error" class="field-error" style="display:none;">This field is required.</span>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-secondary btn-sm" id="modal-prompt-cancel">Cancel</button>
                    <button type="button" class="btn ${isDanger ? 'btn-danger' : 'btn-primary'} btn-sm" id="modal-prompt-confirm">${confirmText}</button>
                </div>
            </div>
        `;

        document.body.appendChild(overlay);

        requestAnimationFrame(() => {
            overlay.classList.add('open');
        });

        const input = overlay.querySelector('#modal-prompt-input');
        const errSpan = overlay.querySelector('#modal-prompt-error');
        const cancelBtn = overlay.querySelector('#modal-prompt-cancel');
        const confirmBtn = overlay.querySelector('#modal-prompt-confirm');

        function cleanup(result) {
            overlay.classList.remove('open');
            document.removeEventListener('keydown', handleKey);
            setTimeout(() => {
                overlay.remove();
                resolve(result);
            }, 200);
        }

        function handleKey(e) {
            if (e.key === 'Escape') {
                cleanup(null);
            }
        }

        cancelBtn.addEventListener('click', () => cleanup(null));
        confirmBtn.addEventListener('click', () => {
            const val = input.value.trim();
            if (!val) {
                errSpan.style.display = 'block';
                input.classList.add('is-invalid');
                input.focus();
                return;
            }
            cleanup(val);
        });

        overlay.addEventListener('click', (e) => {
            if (e.target === overlay) cleanup(null);
        });
        document.addEventListener('keydown', handleKey);

        input.focus();
    });
}

// Global initialization
document.addEventListener('DOMContentLoaded', () => {
    // 1. Mobile navigation drawer toggle
    const mobileToggle = document.getElementById('mobile-nav-toggle');
    const sidebar = document.getElementById('app-sidebar');

    if (mobileToggle && sidebar) {
        mobileToggle.addEventListener('click', () => {
            sidebar.classList.toggle('drawer-open');
        });

        document.addEventListener('click', (e) => {
            if (!sidebar.contains(e.target) && !mobileToggle.contains(e.target)) {
                sidebar.classList.remove('drawer-open');
            }
        });
    }

    // 2. Sign out confirmation modal
    const signoutBtn = document.getElementById('signout-btn');
    const signoutForm = document.getElementById('signout-form');
    if (signoutBtn && signoutForm) {
        signoutBtn.addEventListener('click', async () => {
            const confirmed = await showConfirm({
                title: 'Sign Out Confirmation',
                message: 'Are you sure you want to sign out of UnitSync?',
                confirmText: 'Sign out',
                cancelText: 'Cancel'
            });
            if (confirmed) {
                signoutForm.submit();
            }
        });
    }

    // 3. Convert session flash banners to toasts (Progressive Enhancement)
    //    Skip elements with data-persist="true" — those stay as static banners.
    const flashMessages = document.querySelectorAll('.flash-message');
    flashMessages.forEach((msgEl) => {
        if (msgEl.dataset.persist === 'true') return; // keep as static banner

        let type = 'info';
        if (msgEl.classList.contains('flash-success')) type = 'success';
        else if (msgEl.classList.contains('flash-error')) type = 'error';
        else if (msgEl.classList.contains('flash-warning')) type = 'warning';

        showToast(msgEl.textContent, type);
        msgEl.remove(); // clean up the now-toasted element
    });

    // 4. Password visibility toggle (Eye icon)
    initPasswordToggles();

    // 5. Term Activation confirmation modal
    document.querySelectorAll('.activate-term-form').forEach(form => {
        form.addEventListener('submit', async (e) => {
            e.preventDefault();
            const termName = form.dataset.termName || 'this term';
            const confirmed = await showConfirm({
                title: 'Activate Academic Term',
                message: `Are you sure you want to activate <strong>${termName}</strong>? The currently active term will become inactive.`,
                confirmText: 'Set as Active',
                cancelText: 'Cancel',
                isDanger: false
            });
            if (confirmed) {
                form.submit();
            }
        });
    });

    // 6. Cancel Training Session confirmation modal
    document.querySelectorAll('.cancel-session-form').forEach(form => {
        form.addEventListener('submit', async (e) => {
            e.preventDefault();
            const sessionLabel = form.dataset.sessionLabel || 'this session';
            const confirmed = await showConfirm({
                title: 'Cancel Training Session',
                message: `Are you sure you want to cancel <strong>${sessionLabel}</strong>?`,
                confirmText: 'Cancel Session',
                cancelText: 'Keep Scheduled',
                isDanger: true
            });
            if (confirmed) {
                form.submit();
            }
        });
    });
});

function initPasswordToggles() {
    document.querySelectorAll('.password-toggle-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            const targetId = btn.dataset.target;
            const input = document.getElementById(targetId);
            if (!input) return;

            const eyeOpen = btn.querySelector('.eye-open');
            const eyeClosed = btn.querySelector('.eye-closed');

            if (input.type === 'password') {
                input.type = 'text';
                if (eyeOpen) eyeOpen.style.display = 'none';
                if (eyeClosed) eyeClosed.style.display = 'inline';
                btn.setAttribute('aria-label', 'Hide password');
            } else {
                input.type = 'password';
                if (eyeOpen) eyeOpen.style.display = 'inline';
                if (eyeClosed) eyeClosed.style.display = 'none';
                btn.setAttribute('aria-label', 'Show password');
            }
        });
    });
}
// Close the header user menu on outside click or Escape
document.addEventListener('click', (e) => {
    const menu = document.getElementById('user-menu');
    if (menu && menu.open && !menu.contains(e.target)) menu.removeAttribute('open');
});
document.addEventListener('keydown', (e) => {
    const menu = document.getElementById('user-menu');
    if (e.key === 'Escape' && menu && menu.open) menu.removeAttribute('open');
});

/* ---- components/app-shell.js ---- */
/* UnitSync - App shell behaviour: mobile drawer, user menu, profile form.
   Loaded with `defer` from header.php. No dependencies. */
(function () {
    'use strict';

    var MOBILE_MQ = window.matchMedia('(max-width: 768px)');
    var body = document.body;
    if (!body.classList.contains('app-shell')) return;

    /* ---------------------------------------------------------------------
       Mobile drawer
       The toggle is handled here in the capture phase and the event is
       stopped, so any older handler bound to #mobile-nav-toggle in another
       script will not fire a second time and cancel this one out.
       --------------------------------------------------------------------- */
    var sidebar = document.getElementById('app-sidebar');
    var toggle = document.getElementById('mobile-nav-toggle');
    var backdrop = null;

    if (sidebar && toggle) {
        backdrop = document.createElement('div');
        backdrop.className = 'sidebar-backdrop';
        backdrop.setAttribute('aria-hidden', 'true');
        body.appendChild(backdrop);

        toggle.setAttribute('aria-controls', 'app-sidebar');
        toggle.setAttribute('aria-expanded', 'false');

        var setDrawer = function (open) {
            sidebar.classList.toggle('drawer-open', open);
            body.classList.toggle('nav-open', open);
            toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
        };

        document.addEventListener('click', function (e) {
            if (!e.target.closest) return;
            if (e.target.closest('#mobile-nav-toggle')) {
                e.stopPropagation();
                e.preventDefault();
                setDrawer(!sidebar.classList.contains('drawer-open'));
            }
        }, true);

        backdrop.addEventListener('click', function () { setDrawer(false); });

        sidebar.addEventListener('click', function (e) {
            if (e.target.closest && e.target.closest('a')) setDrawer(false);
        });

        var onViewportChange = function (e) { if (!e.matches) setDrawer(false); };
        if (MOBILE_MQ.addEventListener) MOBILE_MQ.addEventListener('change', onViewportChange);
        else if (MOBILE_MQ.addListener) MOBILE_MQ.addListener(onViewportChange);

        document.addEventListener('keydown', function (e) {
            if (e.key === 'Escape' && sidebar.classList.contains('drawer-open')) {
                setDrawer(false);
                toggle.focus();
            }
        });
    }

    /* ---------------------------------------------------------------------
       User menu: close on outside click and Escape
       (Sign out is intentionally left to the existing handler on #signout-btn.)
       --------------------------------------------------------------------- */
    var menu = document.getElementById('user-menu');
    if (menu) {
        document.addEventListener('click', function (e) {
            if (menu.open && !menu.contains(e.target)) menu.open = false;
        });
        document.addEventListener('keydown', function (e) {
            if (e.key === 'Escape' && menu.open) {
                menu.open = false;
                var summary = menu.querySelector('summary');
                if (summary) summary.focus();
            }
        });
    }

    /* ---------------------------------------------------------------------
       Profile form: dirty tracking, inline validation, live identity card
       --------------------------------------------------------------------- */
    var form = document.getElementById('profile-form');
    if (!form) return;

    var saveBtn = document.getElementById('profile-save');
    var resetBtn = document.getElementById('profile-reset');
    var inputs = Array.prototype.slice.call(form.querySelectorAll('input.us-input:not([readonly])'));
    var liveName = document.querySelector('[data-live-name]');
    var liveInitials = document.querySelector('[data-live-initials]');
    var liveUser = document.querySelector('[data-live-username]');
    var initial = {};

    var NAME_RE = /^[\p{L}\p{M}][\p{L}\p{M} .'\-]*$/u;
    var USER_RE = /^[A-Za-z0-9._-]{3,30}$/;

    // data-original holds the saved value, so a re-rendered form with posted
    // (invalid) values still counts as unsaved.
    inputs.forEach(function (el) {
        initial[el.name] = el.hasAttribute('data-original') ? el.getAttribute('data-original') : el.value;
    });

    function fieldOf(el) { return el.closest('.us-field'); }

    function validate(el) {
        var v = el.value.trim();
        var msg = '';
        if (el.name === 'username') {
            if (!USER_RE.test(v)) msg = 'Use 3-30 letters, numbers, dots, dashes or underscores.';
        } else {
            if (v === '') msg = 'This field is required.';
            else if (v.length > 50) msg = 'Keep it to 50 characters or fewer.';
            else if (!NAME_RE.test(v)) msg = 'Use letters, spaces, hyphens, apostrophes or periods only.';
        }
        var wrap = fieldOf(el);
        var err = wrap && wrap.querySelector('.us-error');
        if (wrap) wrap.classList.toggle('has-error', msg !== '');
        if (err) err.textContent = msg;
        el.setAttribute('aria-invalid', msg ? 'true' : 'false');
        return msg === '';
    }

    function isDirty() {
        return inputs.some(function (el) { return el.value !== initial[el.name]; });
    }

    function syncIdentity() {
        var first = (form.elements.first_name && form.elements.first_name.value.trim()) || '';
        var last = (form.elements.last_name && form.elements.last_name.value.trim()) || '';
        if (liveName) liveName.textContent = (first + ' ' + last).trim();
        if (liveInitials) {
            var s = (first.charAt(0) + last.charAt(0)).toUpperCase();
            liveInitials.textContent = s || '?';
        }
        var un = form.elements.username;
        if (liveUser && un && !un.readOnly) {
            liveUser.textContent = un.value.trim() || initial.username || '';
        }
    }

    function syncButtons() {
        var dirty = isDirty();
        if (saveBtn) saveBtn.disabled = !dirty;
        if (resetBtn) resetBtn.disabled = !dirty;
    }

    inputs.forEach(function (el) {
        el.addEventListener('input', function () {
            if (fieldOf(el).classList.contains('has-error')) validate(el);
            syncIdentity();
            syncButtons();
        });
        el.addEventListener('blur', function () { validate(el); });
    });

    form.addEventListener('submit', function (e) {
        var ok = true;
        inputs.forEach(function (el) { el.value = el.value.trim(); if (!validate(el)) ok = false; });
        if (!ok) {
            e.preventDefault();
            var bad = form.querySelector('.has-error input');
            if (bad) bad.focus();
        }
    });

    form.addEventListener('reset', function (e) {
        e.preventDefault();
        inputs.forEach(function (el) {
            el.value = initial[el.name];
            var wrap = fieldOf(el), err = wrap && wrap.querySelector('.us-error');
            if (wrap) wrap.classList.remove('has-error');
            if (err) err.textContent = '';
            el.removeAttribute('aria-invalid');
        });
        syncIdentity();
        syncButtons();
    });

    syncButtons();
})();
